INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M15-WB-T000-SE2012', 'HDSAT-RW-M15-WB-T000-SE2012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A regional education office is describing adult literacy rate in Brazil using World Bank figures for 2012 through 2016.', 'Which statement about the graphed change is supported by the data?', '[{"id": "A", "text": "Between 2012 and 2016, Brazil''s adult literacy rate rose overall, from 91.3% to 92.8%."}, {"id": "B", "text": "It peaked in 2014, at 91.7%."}, {"id": "C", "text": "Between 2012 and 2016, Brazil''s adult literacy rate fell overall, from 91.3% to 92.8%."}, {"id": "D", "text": "It stayed essentially unchanged across the period, ending near 91.7%."}]'::jsonb, '{"type": "line_chart", "caption": "Adult literacy rate in Brazil, 2012-2016", "x_label": "Year", "y_label": "percent of adults", "series": [{"label": "2012", "value": 91.3}, {"label": "2013", "value": 91.5}, {"label": "2014", "value": 91.7}, {"label": "2015", "value": 92.0}, {"label": "2016", "value": 92.8}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_rele