INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M15-WB-D027-SP2000', 'C', ARRAY['C']::TEXT[], 'The bars show Kenya at 2.4 years, the tallest gain; Norway is lower at 1.4 years.', '{"D": "Norway''s gain is smaller than Kenya''s.", "A": "Kenya''s bar shows a decline, not the largest increase.", "B": "5.4 years is not the change plotted for Kenya."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M15-WB-T028-SE2005', 'HDSAT-RW-M15-WB-T028-SE2005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A regional education office is describing adult literacy rate in Mexico using World Bank figures for 2005 through 2009.', 'Which statement about the graphed change is supported by the data?', '[{"id": "A", "text": "Between 2005 and 2009, Mexico''s adult literacy rate fell overall, from 91.6% to 93.4%."}, {"id": "B", "text": "It peaked in 2007, at 92.8%."}, {"id": "C", "text": "It stayed essentially unchanged across the period, ending near 92.8%."}, {"id": "D", "text": "Between 2005 and 2009, Mexico''s adult literacy rate rose overall, from 91.6% to 93.4%."}]'::jsonb, '{"type": "line_chart", "caption": "Adult literacy rate in Mexico, 2005-2009", "x_label": "Year", "y_label": "percent of adults", "series": [{"label": "2005", "value": 91.6}, {"label": "2006", "value": 91.7}, {"label": "2007", "value": 92.8}, {"label": "2008", "value": 92.9}, {"label": "2009", "value": 93.4}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_rele