INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M15-WB-T054-SE2017', 'B', ARRAY['B']::TEXT[], 'The line begins at 93.1% in 2017 and ends at 94.8% in 2021, so the overall movement is a rise. The highest point shown is 94.8%, not the middle year.', '{"A": "The endpoints move rose, not fell.", "D": "A change from 93.1% to 94.8% is not an unchanged series.", "C": "2019 is not the highest point; the graph reaches 94.8%."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
