INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M15-WB-T079-IT2000', 'HDSAT-RW-M15-WB-T079-IT2000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A telecommunications report is describing internet use in United States using World Bank figures for 2000 through 2004.', 'Which statement about the graphed change is supported by the data?', '[{"id": "A", "text": "Between 2000 and 2004, United States''s internet use fell overall, from 43.1% to 64.8%."}, {"id": "B", "text": "It peaked in 2002, at 58.8%."}, {"id": "C", "text": "It stayed essentially unchanged across the period, ending near 58.8%."}, {"id": "D", "text": "Between 2000 and 2004, United States''s internet use rose overall, from 43.1% to 64.8%."}]'::jsonb, '{"type": "line_chart", "caption": "Internet use in United States, 2000-2004", "x_label": "Year", "y_label": "percent of the population", "series": [{"label": "2000", "value": 43.1}, {"label": "2001", "value": 49.1}, {"label": "2002", "value": 58.8}, {"label": "2003", "value": 61.7}, {"label": "2004", "value": 64.8}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution,